 enter(location){if(!this.onFoot||this.interior)return false;this.returnPoint={x:this.avatar.x,y:this.avatar.y,location};this.interior=makeInterior(location);this.avatar.scene=location.id;this.avatar.x=550;this.avatar.y=655;this.avatar.vx=this.avatar.vy=0;this.sim.particles=[];this.sim.skids=[];this.sim.event('scene');if(!this.people.some(p=>p.ambient===location.id)&&['restaurant','cafe','studio','clinic'].includes(location.kind))for(const [x,y] of [[180,390],[900,550]])this.people.push(humanActor(x,y,'ped',{scene:location.id,stationary:true,ambient:location.id}));this.sim.story?.interact(location.id);return true;}
