 shoot(){if(!this.onFoot||!this.avatar.alive||this.reloadTimer||this.fireTimer>0)return;const s=this.sim,a=this.avatar,w=WEAPONS.find(w=>w.id===this.weaponId);if(this.clip[w.id]<=0){this.reload();return;}this.clip[w.id]--;this.armory[w.id].ammo=Math.max(0,this.armory[w.id].ammo-1);this.fireTimer=w.rate;for(let i=0;i<w.pellets;i++){const angle=a.angle+(s.rng()-.5)*w.spread;this.bullets.push({x:a.x+Math.cos(angle)*19,y:a.y+Math.sin(angle)*19,px:a.x,py:a.y,vx:Math.cos(angle)*w.speed,vy:Math.sin(angle)*w.speed,range:w.range,damage:w.damage,owner:'player',scene:this.scene(),life:2});}this.shotCount++;if(this.shotCount%4===0)this.raiseWanted(1);for(const p of this.people)if(p.kind==='ped'&&distance(p,a)<700)p.alert=6;s.event('shot');s.event('armory-save',{armory:this.armory});}
 hit(a,amount,source='enemy'){if(!a.alive||a.invulnerable>0)return;const absorbed=Math.min(a.armor||0,amount*.6);a.armor=Math.max(0,(a.armor||0)-absorbed);a.hp=Math.max(0,a.hp-amount+absorbed);a.hit=.18;a.lastHit=this.sim.time;a.invulnerable=a===this.avatar?.16:0;if(!a.hp){a.alive=false;a.death=10;if(a===this.avatar){this.sim.event('hit');return;}if(a.kind==='ped'&&source==='player'){this.raiseWanted(Math.min(5,this.sim.heatLevel+1));this.sim.score=Math.max(0,this.sim.score-150);}else if(a.kind!=='ped'){this.sim.score+=a.kind==='swat'?180:90;this.missionKills++;if(a.ownerCar&&this.people.filter(p=>p.ownerCar===a.ownerCar&&p.alive).length===0){a.ownerCar.abandoned=true;a.ownerCar.abandonedAt=this.sim.time;}if(a.kind==='mafia')this.sim.cash+=25;}}}
