  if(a.kind==='ped'){const moving=[s.player,...s.traffic,...s.cops].find(c=>c!==a&&c.speed>70&&distance(c,a)<100);if(moving){a.alert=1.3;if(distance(moving,a)<28){this.hit(a,35,moving===s.player?'player':'traffic');if(moving===s.player)this.raiseWanted(1);}}a.alert=Math.max(0,a.alert-dt);if(a.alert>0){const angle=Math.atan2(a.y-target.y,a.x-target.x);a.angle=angle;a.x+=Math.cos(angle)*135*dt;a.y+=Math.sin(angle)*135*dt;}else{if(!a.walkTarget||distance(a,a.walkTarget)<28){const n=nearestRoadNode(w,a),next=n&&w.navIndex.get(n.neighbors[Math.floor(s.rng()*n.neighbors.length)]);a.walkTarget=next||n;}if(a.walkTarget){a.angle=Math.atan2(a.walkTarget.y-a.y,a.walkTarget.x-a.x);a.x+=Math.cos(a.angle)*43*dt;a.y+=Math.sin(a.angle)*43*dt;}}pushHuman(a,w);return;}
